/* Includes ------------------------------------------------------------------*/
#include "ax_speed.h"
#include "ax_robot.h"


/**
  * @简  述  电机PID控制函数
  * @参  数  spd_target:编码器速度目标值 ,范围（±250）
  *          spd_current: 编码器速度当前值
  * @返回值  电机PWM速度
  */
/* @L36 函数说明里的单位是错的 --------------------------------
 * 注释写"范围（±250）"，但入参实际是 m/s（满速约 ±1.5）。
 * 这是从旧版本（编码器计数值作为控制量）遗留下来的注释。
 * A/B 两个函数除 static 变量各自独立外完全相同 —— 复制粘贴两份是为了
 * 让两路电机各有自己的"历史状态"（pwm_out、bias_last）。
 * 若改成一个函数用结构体保存状态会更清晰，但厂商选择了最省事的写法。
 * ------------------------------------------------------------- */
int16_t AX_SPEED_PidCtlA(float spd_target, float spd_current)
{
	static int16_t motor_pwm_out;
	static float bias,bias_last;

	//获得偏差值
	bias = spd_target - spd_current;
	
	//PID计算电机输出PWM值
/* @L45 增量式核心（重点）---------------------------------------
 * 注意是 "+=" 而不是 "="：输出是累加出来的，这就是它自带积分的原因。
 * 量级示例：启动瞬间 e≈0.5 m/s，Kp·e=350，Kd·e=450 -> 一拍就 +800，
 * 约 5 拍(100ms)到满幅 4200 —— 起步响应很快，也意味着容易超调振荡。
 * 若实车出现"低速抖动/嗡嗡响"，第一嫌疑就是这两个增益过大，
 * 可先减半试（Kp 700->350, Kd 900->450），不要一次改到 0。
 * ------------------------------------------------------------- */
	motor_pwm_out += ax_motor_kp*bias + ax_motor_kd*(bias-bias_last);
	
	//记录上次偏差
	bias_last = bias;
	
	//限制最大输出
	if(motor_pwm_out > 4200)
		motor_pwm_out = 4200;
	if(motor_pwm_out < -4200)
		motor_pwm_out = -4200;
	
	//返回PWM控制值
	return motor_pwm_out;
}	

/**
  * @简  述  电机PID控制函数
  * @参  数  spd_target:编码器速度目标值 
  *          spd_target: 编码器速度当前值
  * @返回值  电机PWM速度
  */
int16_t AX_SPEED_PidCtlB(float spd_target, float spd_current)
{
	static int16_t motor_pwm_out;
	static float bias,bias_last;

	//获得偏差值
	bias = spd_target - spd_current;
	
	//PID计算电机输出PWM值
	motor_pwm_out += ax_motor_kp*bias + ax_motor_kd*(bias-bias_last);
	
	//记录上次偏差
	bias_last = bias;
	
	//限制最大输出
	if(motor_pwm_out > 4200)
		motor_pwm_out = 4200;
	if(motor_pwm_out < -4200)
		motor_pwm_out = -4200;
	
	//返回PWM控制值
	return motor_pwm_out;
}


